import { formatFileSize } from '@ai-matrx/kit/format';
import { z } from 'zod';
import { runFrameworkPattern } from '../framework-sources';
import type { ExtractionMode } from '../types';

export const nextDataConfigSchema = z.object({
  source: z.string().optional(),
  key_path: z.union([z.string(), z.array(z.string())]),
});
export type NextDataConfig = z.infer<typeof nextDataConfigSchema>;

/**
 * Names of window-bound state blobs we detect via inline-script regex.
 * detectInPage crosses the chrome.scripting boundary and cannot reference
 * outer-scope identifiers.
 *
 * Sites this catches:
 *   - Indeed       → window._initialData
 *   - Reddit       → window.___r (similar pattern)
 *   - Reactjs apps → window.__INITIAL_STATE__ / __PRELOADED_STATE__
 *   - Vue/Nuxt     → window.__INITIAL_DATA__
 *   - Apollo       → window.__APOLLO_STATE__ (also detected separately)
 */
export const nextDataMode: ExtractionMode<NextDataConfig> = {
  id: 'next_data',
  label: 'Framework',
  description:
    'Read embedded framework data (Next.js, Nuxt, Apollo, Indeed _initialData, Redux preloaded state). Pick a key path with the JSON tree to extract rows.',
  configSchema: nextDataConfigSchema,
  defaultConfig: () => ({ key_path: '' }),

  detectInPage: () => {
    // WEIGHTS ARE BYTES, MEASURED HERE (2026-09-12). A payload's weight is a
    // byte question, and `.length` of text is UTF-16 code units — on a Japanese
    // page the real payload is ~3x what `.length` reports. TextEncoder exists in
    // the page realm with no import, so the probe measures UTF-8 bytes itself.
    const encoder = new TextEncoder();
    const found: { source: string; sizeBytes: number }[] = [];
    const checkScript = (id: string, node: Element | null) => {
      if (!node?.textContent) return;
      try {
        JSON.parse(node.textContent);
        found.push({ source: id, sizeBytes: encoder.encode(node.textContent).length });
      } catch {
        // skip
      }
    };
    checkScript('__NEXT_DATA__', document.getElementById('__NEXT_DATA__'));
    checkScript('__NUXT_DATA__', document.getElementById('__NUXT_DATA__'));
    checkScript('__APOLLO_STATE__', document.getElementById('__APOLLO_STATE__'));

    // LinkedIn Voyager hydration: <code id="bpr-guid-*"> blocks.
    const bprBlocks = document.querySelectorAll<HTMLElement>('code[id^="bpr-guid-"]');
    if (bprBlocks.length > 0) {
      let totalBytes = 0;
      let parsedCount = 0;
      for (const b of Array.from(bprBlocks)) {
        try {
          JSON.parse(b.textContent ?? '');
          parsedCount++;
          totalBytes += encoder.encode(b.textContent ?? '').length;
        } catch {
          // skip
        }
      }
      if (parsedCount > 0) {
        found.push({ source: `bpr-guid (LinkedIn) ×${parsedCount}`, sizeBytes: totalBytes });
      }
    }

    // Inline window.* state — paren-balanced scan to handle JS object
    // literals (Indeed, Reddit, etc.) where JSON.parse fails.
    const WINDOW_NAMES = [
      '_initialData',
      '__INITIAL_STATE__',
      '__INITIAL_DATA__',
      '__PRELOADED_STATE__',
      '__APP_STATE__',
      '__REDUX_STATE__',
      '__APOLLO_STATE__',
      '__SERVER_STATE__',
    ];
    const inlineScripts = Array.from(
      document.querySelectorAll<HTMLScriptElement>('script:not([src])'),
    );
    for (const name of WINDOW_NAMES) {
      let bestBytes = 0;
      const escName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const lhsRe = new RegExp(
        `(?:window\\.|self\\.|var\\s+|let\\s+|const\\s+)?${escName}\\s*=\\s*`,
        'g',
      );
      for (const s of inlineScripts) {
        const txt = s.textContent ?? '';
        if (!txt.includes(name)) continue;
        lhsRe.lastIndex = 0;
        let m: RegExpExecArray | null;
        while ((m = lhsRe.exec(txt))) {
          const start = m.index + m[0].length;
          const opener = txt[start];
          if (opener !== '{' && opener !== '[') continue;
          // Quick paren-balanced length scan.
          let i = start;
          let depth = 0;
          let inStr: string | null = null;
          while (i < txt.length) {
            const ch = txt[i];
            if (inStr) {
              if (ch === '\\') {
                i += 2;
                continue;
              }
              if (ch === inStr) inStr = null;
              i++;
              continue;
            }
            if (ch === '"' || ch === "'" || ch === '`') {
              inStr = ch;
              i++;
              continue;
            }
            if (ch === '{' || ch === '[') depth++;
            else if (ch === '}' || ch === ']') {
              depth--;
              if (depth === 0) {
                i++;
                break;
              }
            }
            i++;
          }
          if (depth === 0) {
            const spanBytes = encoder.encode(txt.slice(start, i)).length;
            if (spanBytes > bestBytes) bestBytes = spanBytes;
          }
        }
      }
      if (bestBytes > 0) found.push({ source: `window.${name}`, sizeBytes: bestBytes });
    }

    if (found.length === 0) {
      return { available: false, summary: 'No embedded framework data' };
    }
    // NO FORMATTING IN THE PAGE. The sizes travel as NUMBERS in `meta.sources`
    // and `summarize` below turns them into a sentence in the extension realm,
    // where `formatFileSize` exists. This line used to read
    // `${f.source} (${(f.size / 1024).toFixed(1)} KB)` — a byte-size formatter
    // (over a character count, until the probe measured bytes) that was silently allowlisted because "it can't import across the
    // chrome.scripting boundary". True, and not a reason: the probe reports
    // facts, the extension renders them.
    return {
      available: true,
      summary: found.map((f) => f.source).join(', '),
      count: found.length,
      meta: { sources: found },
    };
  },

  /**
   * "__NEXT_DATA__ (12.7 KB), window._initialData (48.3 KB)". Runs in the
   * extension realm on the hint the probe returned, so the number is
   * `formatFileSize`'s — which also means a 3 MB blob now reads "3.0 MB"
   * instead of the old "3072.0 KB".
   */
  summarize: (hint) => {
    const sources = hint.meta?.sources;
    if (!Array.isArray(sources) || sources.length === 0) return hint.summary;
    return sources
      .map((entry) => {
        const { source, sizeBytes } = entry as { source?: unknown; sizeBytes?: unknown };
        const name = typeof source === 'string' ? source : 'unknown source';
        return typeof sizeBytes === 'number' ? `${name} (${formatFileSize(sizeBytes)})` : name;
      })
      .join(', ');
  },

  runInExtension: runFrameworkPattern,
  runInPage: () => {
    throw new Error('Framework extraction requires decoded sources in the extension runner.');
  },
};
