let bootstrapped = false;
const STALE_OFFSCREEN_PREFLIGHT_TIMEOUT_MS = 5_000;

export function bootstrapBackground(): void {
  if (bootstrapped) return;
  bootstrapped = true;
  startDebugRelay();
  // Restore the Debug → Bridges traffic-buffer flag (off by default; persisted).
  void hydrateBridgeTrafficEnabled();
  log.info('sw', 'background bootstrap (sync)');
  // Emit the runtime identity bundle (extension id, redirect URI, OAuth
  // client id) so any future ID drift is visible in the user's debug log
  // before sign-in is ever attempted. See .research/v0.1.4-auth-incident.md.
  logExtensionIdentityOnce();

  // ── 0. Close any STALE offscreen document that survived an extension
  //       reload. MV3 offscreen documents can outlive a SW reload — when the
  //       user runs `pnpm build` and reloads the extension, the sidepanel
  //       loads NEW JS but the offscreen keeps running OLD JS. That's how
  //       the v0.1.16 audio bug shipped: sidepanel expected base64 strings,
  //       offscreen broadcast ArrayBuffer (which JSON-serializes to `{}`).
  //       Closing eagerly here guarantees the next `ensureOffscreen` call
  //       creates a fresh document with the latest bundle.
  // The reconnect path creates the same singleton document. Keep it behind
  // this cleanup: otherwise a reload can open a fresh desktop socket and
  // then asynchronously close its new offscreen owner, leaving the desktop
  // healthy but without an extension session.
  const staleOffscreenCleanup = closeStaleOffscreenOnBoot();
  deferOffscreenAcquisitionUntil(staleOffscreenCleanup);

  // ── 1. Register message handlers SYNCHRONOUSLY so they're ready immediately.
  registerHandlers();
  registerSafariAuthorizationBackground();
  // The WS router belongs in this synchronous block for the same reason: a
  // retained offscreen document can wake this worker with an epoch
  // handshake or a URL re-resolve before any async boot step has run.
  installWsRouter();
  registerDesktopRediscoverHandler();

  // ── 1a. Token broker — the SW owns the canonical in-memory credential
  //        cache; sidepanel/offscreen mint + consume through these channels
  //        (src/lib/broker/). Tokens are memory-only, never persisted.
  registerBrokerHandlers();
  // "Save this login?" host — raw value-bearing listener + value-free bus handlers.
  registerCredentialCaptureHost();
  registerInlineCredentialSuggestionHost();
  registerGeneratedPasswordHost();
  registerCredentialAssistanceStatus();
  // Chrome retains action state across MV3 worker suspension while saved-login
  // offers do not. Validated capture state reprojects only after that clear.
  void reconcileCredentialAssistanceActionOnBoot().then(() =>
    rehydrateCredentialCaptureCandidates(),
  );

  // ── 2. Tool dispatcher subscribes to STREAM_OPENED + STREAM_CHUNK.
  //       Per-run permission mode is latched from the chat hook; this default
  //       only kicks in if the sidepanel forgot to pass one.
  startToolDispatcher({ defaultPermissionMode: () => 'ask' });

  // ── 2a. Audio log: track when each tab last produced sound so
  //        `tab_audio_inspect` can answer "recently audible" queries.
  startAudibleLog();

  // ── 3. Alarms — also synchronous registration.
  setupAlarms();
  startDesktopProbeAlarm();
  void startAgendaScanner();
  registerAgendaNotificationClicks();

  // ── 3. Async housekeeping: restore the Supabase identity BEFORE any
  //       RLS-backed discovery or Realtime subscription. Starting these in
  //       parallel made cold service-worker boots race as anonymous users:
  //       remote app_instances discovery returned no rows and private
  //       Broadcast channels could fail their first subscribe.
  void staleOffscreenCleanup.then(async () => {
    await rehydrateSupabaseSession();
    const state = await probeDesktop();
    lastDesktopTransport = state.transport;
    lastDesktopHealthKey = desktopHealthSnapshotKey(state.health);
    broadcast(CHANNELS.DESKTOP_AVAILABILITY, {
      transport: state.transport,
      health: state.health,
      lastChecked: state.lastChecked,
    });
    // Phase 2 C2.a — open the persistent WS only when HTTP transport is
    // active. Native messaging IS already a long-lived bidirectional
    // channel; doubling up would waste resources.
    if (state.transport === 'http') {
      void connectWs();
    }
    // Supabase Broadcast is RLS-backed and therefore belongs after session
    // restoration too. It remains best-effort: failures log, never throw.
    void connectBroadcast();
  });

  // ── 4. WebMCP page-side bridge: when an allowlisted page finishes
  //       loading, register matrx-extend's tools on its
  //       `document.modelContext` so external agents on the page can
  //       discover and call them.
  registerWebmcpTabUpdateGate();

  // ── 5. Phase 2 C1 — externally_connectable bridge from matrx-frontend.
  //       Allowlisted page origins (configured in wxt.config.ts) can talk
  //       to us via chrome.runtime.sendMessage(extId, FRONTEND_RPC envelope).
  registerFrontendRpcExternalListener();

  // ── 6. Phase 2 C1.c — Supabase Broadcast subscriber for the same
  //       FRONTEND_RPC envelope shape (per-user channel). Its connection is
  //       started by step 3 after the Supabase session is restored.

  // ── 6b. Phase 3c.1 — scheduler host. Subscribes to sch_task changes for the
  //        signed-in user and runs any task that targets this surface
  //        ('chrome-extension-chat'). Idempotent at the host layer; safe to
  //        re-invoke on every SW boot. The sidepanel-side auth flow already
  //        writes USER_PROFILE before any UI work, so checking it here
  //        captures both the cold-boot case (already signed in) and the
  //        wake-after-idle case.
  void startSchedulerHostIfSignedIn();
  registerSchedulerHostUserWatcher();

  // ── 7. Phase 2 C2 — persistent WebSocket reverse channel with matrx-local.
  //       Wired via the offscreen document (long-lived) — opens lazily when
  //       the desktop bridge is reachable over HTTP. If native messaging is
  //       the active transport, that connection IS the reverse channel and
  //       we skip WS.
  startLocalBrowserController();
  registerWsReverseInvocationHandler();

  // ── 7b. Right-click context menus. "Ask Matrx about \"%s\"" pre-fills
  //        the chat draft with the page selection; "Open Matrx side panel"
  //        is a fallback for users who haven't pinned the action button.
  setupContextMenus();

  // ── 8. Pilot session lifecycle (CLAUDE.md roadmap item #9).
  //       Watch for tab / group removal so we can reset the persisted pilot
  //       session record when its group disappears externally (last tab
  //       closed by the user, group dissolved, etc.). Without this the
  //       sidepanel would think a pilot session is still active and refuse
  //       new actions until the user explicitly clicked "End Session".
  registerPilotLifecycleListeners();

  // CDP listener registration + orphaned-attachment sweep (audit P1/P2-7).
  // Listeners were lazily installed inside attach(), so an SW restart with a
  // surviving chrome.debugger attachment dropped every event and left the
  // "is being debugged" banner stuck until tab close.
  reconcileCdpOnBoot();

  // Phantom-session sweep (audit P1-12): tab-group ids are NOT stable
  // across browser restarts, and if Chrome exited with a Pilot session
  // active no removal event ever fired (the extension wasn't running).
  // The persisted record then pointed at a group id matching nothing —
  // and `enforcePilotGroupScope` rejected EVERY action-tier tool
  // (including normal Assistant runs) with pilot_group_violation until
  // the user manually ended the phantom session. `isGroupValid()`
  // existed for exactly this but had zero callers.
  void (async () => {
    try {
      const session = await getPilotSessionSnapshotAsync();
      if (!session.active) return;
      const valid = await usePilotStore.getState().isGroupValid();
      if (!valid) {
        log.info('pilot', 'boot sweep: persisted session group no longer exists — resetting');
        usePilotStore.getState().resetLocal();
      }
    } catch (err) {
      log.warn('pilot', 'boot session validation failed', err);
    }
  })();
}

let lastDesktopTransport: 'native' | 'http' | 'none' | null = null;
let lastDesktopHealthKey = '';

function setupAlarms(): void {
  chrome.alarms.onAlarm.addListener(async (alarm) => {
    if (alarm.name === ALARMS.TOKEN_REFRESH) {
      console.log('[matrx-extend] alarm: token refresh');
      try {
        const refreshed = await refreshAccessToken();
        if (!refreshed) {
          // Transient failure (network down, server hiccup): the alarm is
          // one-shot and only re-armed on SUCCESS inside scheduleRefresh —
          // without this retry, proactive refresh silently stopped for the
          // rest of the session (audit P2: TOKEN_REFRESH not re-armed).
          // Only retry while a refresh token actually exists; a signed-out
          // / signed-out-by-failure state must not loop a dead alarm.
          const stored = await chrome.storage.local.get([STORAGE_KEYS.REFRESH_TOKEN_ENC]);
          if (stored[STORAGE_KEYS.REFRESH_TOKEN_ENC]) {
            chrome.alarms.create(ALARMS.TOKEN_REFRESH, { delayInMinutes: 5 });
          }
        }
      } catch (err) {
        console.warn('[matrx-extend] token refresh alarm failed — retrying in 5min', err);
        chrome.alarms.create(ALARMS.TOKEN_REFRESH, { delayInMinutes: 5 });
      }
      await rehydrateSupabaseSession();
    } else if (alarm.name === ALARMS.DESKTOP_PROBE) {
      const state = await probeDesktop();
      const healthKey = desktopHealthSnapshotKey(state.health);
      // Broadcast when transport or managed-service health changes.
      if (state.transport !== lastDesktopTransport || healthKey !== lastDesktopHealthKey) {
        const prev = lastDesktopTransport;
        lastDesktopTransport = state.transport;
        lastDesktopHealthKey = healthKey;
        if (state.transport !== prev) {
          log.info('desktop', `transport changed → ${state.transport}`);
        } else {
          log.info('desktop', `health changed → ${state.health?.health ?? 'ok'}`);
        }
        broadcast(CHANNELS.DESKTOP_AVAILABILITY, {
          transport: state.transport,
          health: state.health,
          lastChecked: state.lastChecked,
        });
        // Phase 2 C2 — open WS when HTTP transport just became active
        // (and we weren't on HTTP before).
        if (state.transport === 'http' && prev !== 'http') {
          void connectWs();
        }
      }
      // A healthy engine with a dead socket used to be a permanent state:
      // the block above only fires on a TRANSPORT CHANGE, and the offscreen
      // stops retrying once its backoff ceiling is reached. This probe is
      // the recovery path — it re-resolves the URL and reopens whenever the
      // engine is reachable but the socket FAILED. It deliberately does not
      // reopen a socket the offscreen idled out on purpose; that one comes
      // back on the next outbound send.
      if (state.transport === 'http' && shouldBackgroundReopenWs()) {
        void connectWs();
      }
    } else if (alarm.name === ALARMS.AGENDA_SCAN) {
      await scanAndNotify();
    }
  });
}

function registerHandlers(): void {
  on<StartStreamArgs, { ok: boolean }>(CHANNELS.STREAM_START, async (payload) => {
    // Latch run metadata BEFORE forwarding to offscreen so the dispatcher
    // has everything ready by the time the first tool_event lands.
    // Seeding `permissionMode` here (not only from STREAM_OPENED) is
    // race-proof against a fast tool_delegated arriving before
    // STREAM_OPENED is processed — see recordAssignedTab's docstring.
    if (payload.runId) {
      recordAssignedTab(payload.runId, payload.assignedTabId ?? null, {
        ...(payload.permissionMode !== undefined && {
          permissionMode: payload.permissionMode,
        }),
        agentName: payload.agentName ?? null,
      });
    }
    await startStream(payload);
    return { ok: true };
  });

  on<{ runId: string }, { ok: boolean }>(CHANNELS.STREAM_CANCEL, async (payload) => {
    await cancelStream(payload.runId);
    return { ok: true };
  });

  // Mic capture (TASK-002): sidepanel asks the SW to run a mic action;
  // SW ensures offscreen is up, then forwards via MIC_RUN. The actual
  // MediaRecorder lives in the offscreen document where USER_MEDIA reason
  // grants reliable mic access.
  //
  // Failure surfacing — every error path BOTH throws (so the sidepanel's
  // try/catch around sendMicRequest fires onError and the inline banner
  // shows) AND broadcasts a MIC_EVENT.error (so any other open surface
  // listening for mic events sees the failure too). Silent failures here
  // are forbidden — the user's mic button would otherwise hang in the
  // pre-start state with no signal.
  on<MicRequestPayload, { ok: boolean }>(CHANNELS.MIC_REQUEST, async (payload) => {
    log.info('audio', 'sw: MIC_REQUEST received', {
      action: payload.action,
      payload,
    });
    try {
      await ensureOffscreen();
    } catch (err) {
      const message = (err as Error).message ?? 'Failed to open offscreen document';
      log.error('audio', 'sw: ensureOffscreen failed', err);
      broadcast(CHANNELS.MIC_EVENT, {
        type: 'error',
        message: `Couldn't start the microphone backend: ${message}`,
        code: 'OFFSCREEN_UNAVAILABLE',
      });
      throw new Error(message);
    }
    const runPayload: MicRunPayload = payload;
    let res: { __error?: string } | { ok?: true } | null = null;
    try {
      log.info('audio', 'sw: MIC_RUN forward to offscreen', { runPayload });
      res = (await chrome.runtime.sendMessage({
        __matrx: true,
        kind: CHANNELS.MIC_RUN,
        payload: runPayload,
      })) as { __error?: string } | { ok?: true } | null;
      log.info('audio', 'sw: MIC_RUN reply', { res });
    } catch (err) {
      const message = (err as Error).message ?? 'Mic forwarding failed';
      log.error('audio', 'sw: MIC_RUN forward failed', err);
      broadcast(CHANNELS.MIC_EVENT, {
        type: 'error',
        message: `Couldn't reach the mic backend: ${message}`,
        code: 'FORWARD_FAILED',
      });
      throw new Error(message);
    }
    if (res && typeof res === 'object' && '__error' in res && res.__error) {
      const message = res.__error;
      log.error('audio', 'sw: MIC_RUN handler returned error', { message });
      broadcast(CHANNELS.MIC_EVENT, {
        type: 'error',
        message: `Mic backend error: ${message}`,
        code: 'MIC_RUN_FAILED',
      });
      throw new Error(message);
    }
    return { ok: true };
  });

  // Video capture (TASK-003): sidepanel asks the SW to run a tab/display
  // recording. Same offscreen pattern as mic, plus a tab-capture stream id
  // resolution step here in the SW (chrome.tabCapture lives only in the SW
  // context). On 'start' for source==='tab' we resolve the streamId and
  // forward; on 'stop' we just forward the action.
  on<VideoRequestPayload, { ok: boolean }>(CHANNELS.VIDEO_REQUEST, async (payload) => {
    if (payload.action === 'start' && (payload.source ?? 'tab') === 'tab') {
      if (payload.targetTabId == null) {
        broadcast(CHANNELS.VIDEO_EVENT, {
          type: 'error',
          sessionId: payload.sessionId,
          message: 'targetTabId is required for tab capture',
          code: 'NO_TARGET_TAB',
        } satisfies VideoErrorEvent);
        return { ok: false };
      }
      if (!chrome.tabCapture?.getMediaStreamId) {
        broadcast(CHANNELS.VIDEO_EVENT, {
          type: 'error',
          sessionId: payload.sessionId,
          message:
            'Tab video capture not granted. Enable it from the Recorder pane in the Tools tab.',
          code: 'API_UNAVAILABLE',
        } satisfies VideoErrorEvent);
        return { ok: false };
      }
      let streamId: string;
      try {
        streamId = await new Promise<string>((resolve, reject) => {
          chrome.tabCapture.getMediaStreamId({ targetTabId: payload.targetTabId! }, (id) => {
            const err = chrome.runtime.lastError;
            if (err) reject(new Error(err.message ?? 'getMediaStreamId failed'));
            else if (!id) reject(new Error('empty streamId'));
            else resolve(id);
          });
        });
      } catch (err) {
        broadcast(CHANNELS.VIDEO_EVENT, {
          type: 'error',
          sessionId: payload.sessionId,
          message: `tab capture stream id failed: ${(err as Error).message}`,
          code: 'STREAM_ID_FAILED',
        } satisfies VideoErrorEvent);
        return { ok: false };
      }
      await ensureOffscreen();
      const runPayload: VideoRunPayload = { ...payload, streamId };
      await chrome.runtime
        .sendMessage({
          __matrx: true,
          kind: CHANNELS.VIDEO_RUN,
          payload: runPayload,
        })
        .catch((err) => {
          log.error('sys', 'video forward failed', err);
          broadcast(CHANNELS.VIDEO_EVENT, {
            type: 'error',
            sessionId: payload.sessionId,
            message: `forward to offscreen failed: ${(err as Error).message}`,
            code: 'FORWARD_FAILED',
          } satisfies VideoErrorEvent);
        });
      return { ok: true };
    }
    // 'stop' action or non-tab source — pass through. getDisplayMedia runs
    // inside the offscreen document where the picker is permitted.
    await ensureOffscreen();
    const runPayload: VideoRunPayload = { ...payload };
    await chrome.runtime
      .sendMessage({
        __matrx: true,
        kind: CHANNELS.VIDEO_RUN,
        payload: runPayload,
      })
      .catch((err) => log.error('sys', 'video forward failed', err));
    return { ok: true };
  });

  // STREAM_CHUNK is broadcast by offscreen. The sidepanel listens directly;
  // the SW doesn't need to do anything. No handler registered to keep the
  // signal clean.

  on<Parameters<typeof desktopRpc>[0], Awaited<ReturnType<typeof desktopRpc>>>(
    CHANNELS.DESKTOP_RPC,
    (payload) => desktopRpc(payload),
  );

  // Legacy: content scripts use chrome.runtime.sendMessage directly with a
  // {__matrx, kind: PAGE_NAVIGATED, payload} envelope (see src/lib/content/bridge.ts).
  on<{ url: string }, { ack: true }>(CHANNELS.PAGE_NAVIGATED, async (payload) => {
    if (!payload?.url) return { ack: true };
    const lookup = await lookupCapturedByUrl(payload.url);
    if (lookup.status === 'found') {
      broadcast(CHANNELS.PAGE_ALREADY_CAPTURED, {
        url: payload.url,
        capturedAt: lookup.page.captured_at,
        id: lookup.page.id,
      });
    }
    return { ack: true };
  });

  // tab_id stamped for the same two-window scoping as the list picker.
  on<{ fields: { name: string; selector: string }[]; session_id: string }, { ack: true }>(
    CHANNELS.DATA_PICKER_RESULT,
    (payload, sender) => {
      // Relay ONLY genuine content-script events (sender.tab present) — the
      // SW's own broadcast self-delivery would otherwise loop this handler
      // on its own stamped rebroadcast forever.
      if (!payload?.session_id) return { ack: true };
      const stamped = stampDocumentSender(payload, sender);
      if (stamped) broadcast(CHANNELS.DATA_PICKER_RESULT, stamped);
      return { ack: true };
    },
  );

  on<{ session_id: string }, { ack: true }>(CHANNELS.DATA_PICKER_EXIT, (payload, sender) => {
    if (!payload?.session_id) return { ack: true };
    const stamped = stampDocumentSender(payload, sender);
    if (stamped) broadcast(CHANNELS.DATA_PICKER_EXIT, stamped);
    return { ack: true };
  });

  registerListPickerRelays();
  registerDocumentNetworkCaptureHost(runLocalSavedPattern, runLocalNetworkDiscovery);

  // Demo recording: in-page event-capture function calls
  // chrome.runtime.sendMessage with a DEMO_EVENT envelope. We forward to
  // the recorder's per-tab state.
  on<CapturedEvent, { ack: true }>(CHANNELS.DEMO_EVENT, (payload, sender) => {
    onCapturedEvent(payload, sender.tab?.id);
    return { ack: true };
  });

  // Network capture: ISOLATED-world relay forwards every intercepted
  // fetch/XHR via NET_CAPTURE_EVENT. Stamp the sender tab id before
  // rebroadcasting — the sidepanel filters on it so a previously-tapped tab
  // can't pollute another tab's capture session (audit I1). There is NO
  // buffering here: if no sidepanel is listening, the event is dropped.
  on<Record<string, unknown>, { ack: true }>(CHANNELS.NET_CAPTURE_EVENT, (payload, sender) => {
    const stamped = stampDocumentSender(payload, sender);
    if (stamped) broadcast(CHANNELS.NET_CAPTURE_EVENT, stamped);
    return { ack: true };
  });

  // The side panel's package chat delegates a cloud agent's browser tool here
  // (`deviceTools` port). Only extension pages reach this (no tab sender).
  on<
    { callId: string; toolName: string; args: unknown },
    { ok: boolean; result?: unknown; error?: string }
  >(CHANNELS.DEVICE_TOOL_INVOKE, async (payload, sender) => {
    if (sender.tab || sender.id !== chrome.runtime.id) {
      return { ok: false, error: 'device tool: extension pages only' };
    }
    // One run per call id: a hand-off for the same id (the panel closing) joins this run.
    return runDeviceToolOnce(payload, runDeviceToolForAgent);
  });

  // The panel is going away with delegated calls in flight: finish them and deliver the results.
  on<{ calls?: DeviceHandOffCall[] }, { ack: true }>(
    CHANNELS.DEVICE_TOOL_HANDOFF,
    (payload, sender) => {
      if (sender.tab || sender.id !== chrome.runtime.id) return { ack: true };
      void handOffDeviceCalls(
        Array.isArray(payload.calls) ? payload.calls : [],
        deviceHandOffDeps(),
      ).catch((err) => log.error('sw', 'device tool hand-off crashed', err));
      return { ack: true };
    },
  );

  // WebMCP: pages on the allowlist (see src/lib/origin-allowlist.ts) can
  // execute our registered tools through `document.modelContext.executeTool`.
  // The webmcp-bridge content script forwards each call here; we resolve
  // the handler, run it, and reply with `{ ok, result?, error? }`.
  on<
    { callId: string; toolName: string; args: unknown },
    { ok: boolean; result?: unknown; error?: string }
  >(CHANNELS.WEBMCP_CALL, async (payload, sender) => {
    const senderUrl = sender.tab?.url ?? sender.url ?? '';
    if (!senderUrl || !matchesAllowedOrigin(senderUrl)) {
      return { ok: false, error: 'webmcp: origin not allowed' };
    }
    const assignedTabId = sender.tab?.id;
    if (assignedTabId == null) {
      return { ok: false, error: 'webmcp: origin tab unavailable' };
    }
    try {
      await chrome.tabs.get(assignedTabId);
    } catch {
      return { ok: false, error: 'webmcp: origin tab unavailable' };
    }
    const mode = await readDefaultPermissionMode();
    return handleWebmcpCall(payload, {
      permissionMode: mode,
      initiator: 'page',
      assignedTabId,
    });
  });
}

/**
 * A delegated browser tool from the package chat runs through the extension's REAL gate — the
 * same `handleCall` its own chat uses (`runDeviceToolCall`: approval / ask-user cards, Ask/Act,
 * pinned to the tab the person sent from) — never the WebMCP page path, which refuses every
 * ask-user and privileged tool.
 */
async function runDeviceToolForAgent(call: DeviceToolCallRef): Promise<DeviceToolRunAnswer> {
  const mode =
    call.permissionMode === 'act' || call.permissionMode === 'ask'
      ? call.permissionMode
      : await readDefaultPermissionMode();
  if (!call.conversationId) {
    return { ok: false, error: 'device tool: conversationId is required' };
  }
  return runDeviceToolCall({
    callId: call.callId,
    toolName: call.toolName,
    args: call.args,
    conversationId: call.conversationId,
    permissionMode: mode,
    assignedTabId: typeof call.assignedTabId === 'number' ? call.assignedTabId : null,
  });
}

function deviceHandOffDeps(): DeviceHandOffDeps {
  return {
    run: runDeviceToolForAgent,
    deliver: async (conversationId, result) => {
      const { response, delivered } = await deliverToolResult(conversationId, result);
      if (!response.ok) {
        const retryable =
          response.status === 0 ||
          response.status === 408 ||
          response.status === 429 ||
          response.status >= 500;
        // A hard refusal (the server does not know the call) cannot be replayed: report it, do not loop.
        if (!retryable) return { delivered: false, continuation: null };
        throw new Error(`tool_results ${response.status}: ${response.error}`);
      }
      const data = response.data;
      return {
        delivered,
        continuation: data.continuation_needed
          ? { conversationId, userRequestId: data.user_request_id ?? null }
          : null,
      };
    },
    enqueue: (input) => enqueueUndeliveredResult(input),
    continueRun: (signal) => broadcast(CHANNELS.STREAM_CONTINUE, signal),
    report: (message, detail) => log.warn('sw', message, detail),
  };
}

function registerWebmcpTabUpdateGate(): void {
  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
    if (changeInfo.status !== 'complete') return;
    const url = tab.url;
    if (!url || !matchesAllowedOrigin(url)) return;
    try {
      const isAdmin = await readIsAdmin();
      const result = await registerToolsOnActiveTab({ isAdmin, tabId });
      if (result.ok) {
        log.info('sw', `registered ${result.count ?? 0} tools on ${url}`);
      } else if (result.reason && result.reason !== 'WebMCP unavailable') {
        // Don't log "WebMCP unavailable" — it's the expected state on
        // any Chrome older than 146.
        log.info('sw', `register skipped: ${result.reason}`, { url });
      }
    } catch (err) {
      log.warn('sw', `webmcp register failed`, err);
    }
  });
}

async function readIsAdmin(): Promise<boolean> {
  try {
    const r = await chrome.storage.local.get([STORAGE_KEYS.IS_ADMIN]);
    return r[STORAGE_KEYS.IS_ADMIN] === true;
  } catch {
    return false;
  }
}

/**
 * Phase 2 C1.b — listen for `chrome.runtime.sendMessage(extId, envelope)`
 * from allowlisted page origins (configured in `wxt.config.ts`'s
 * `externally_connectable.matches`). Validate the origin against the same
 * allowlist used by WebMCP, validate the envelope shape with Zod, route
 * through `handleFrontendRpc`.
 */
function registerFrontendRpcExternalListener(): void {
  if (!chrome.runtime.onMessageExternal) {
    log.warn('sw', 'chrome.runtime.onMessageExternal unavailable — frontend bridge disabled');
    return;
  }
  chrome.runtime.onMessageExternal.addListener((msg, sender, sendResponse) => {
    // Filter to FRONTEND_RPC envelopes only — Chrome may also deliver
    // messages from other extensions / contexts.
    if (
      !msg ||
      typeof msg !== 'object' ||
      (msg as { channel?: unknown }).channel !== FRONTEND_RPC_CHANNEL
    ) {
      // Not for us; let other listeners (if any) handle it.
      return false;
    }

    // Origin gate. Manifest's externally_connectable already gates ON
    // ORIGIN at the platform layer, but we double-check defensively
    // because Chrome's ID-based externally_connectable (NOT used here)
    // bypasses host matching.
    const senderUrl = sender.url ?? sender.origin ?? '';
    if (!senderUrl || !matchesAllowedOrigin(senderUrl)) {
      const requestId =
        typeof (msg as { requestId?: unknown }).requestId === 'string'
          ? (msg as { requestId: string }).requestId
          : '';
      const reply: FrontendRpcResponse = {
        ok: false,
        error: 'origin not allowed',
        requestId,
      };
      sendResponse(reply);
      log.warn('sw', `frontend-rpc rejected from ${senderUrl}`);
      return false;
    }

    const parsed = FrontendRpcEnvelopeSchema.safeParse(msg);
    if (!parsed.success) {
      const requestId =
        typeof (msg as { requestId?: unknown }).requestId === 'string'
          ? (msg as { requestId: string }).requestId
          : '';
      const reply: FrontendRpcResponse = {
        ok: false,
        error: `invalid envelope: ${JSON.stringify(parsed.error.format())}`,
        requestId,
      };
      sendResponse(reply);
      return false;
    }

    // GESTURE-CRITICAL: `sender.tab` is read here, synchronously, and handed
    // down. handleFrontendRpc uses it to invoke chrome.sidePanel.open() before
    // its first `await` — the `chrome.tabs.query()` that used to answer the
    // same question was an await, and spent the gesture Chrome gave us.
    // src/lib/frontend-bridge/panel-gesture.ts.
    handleFrontendRpc(parsed.data, {
      url: senderUrl,
      origin: sender.origin,
      tabId: sender.tab?.id,
      windowId: sender.tab?.windowId,
    })
      .then((response) => {
        // Optional Debug-tab buffer (no-op when disabled).
        recordBridgeTraffic({
          stream: 'frontend-rpc',
          direction: 'in',
          action: parsed.data.action,
          requestId: parsed.data.requestId,
          sender: senderUrl,
          payload: parsed.data.payload,
          response,
          ok: response.ok,
          ...(!response.ok && { error: response.error }),
        });
        try {
          sendResponse(response);
        } catch {
          // Channel may have closed; nothing we can do.
        }
      })
      .catch((err) => {
        const reply: FrontendRpcResponse = {
          ok: false,
          error: (err as Error)?.message ?? 'handler crashed',
          requestId: parsed.data.requestId,
        };
        recordBridgeTraffic({
          stream: 'frontend-rpc',
          direction: 'in',
          action: parsed.data.action,
          requestId: parsed.data.requestId,
          sender: senderUrl,
          payload: parsed.data.payload,
          response: reply,
          ok: false,
          error: reply.error,
        });
        try {
          sendResponse(reply);
        } catch {
          /* channel closed */
        }
      });
    return true; // keep the message channel open for async sendResponse
  });
  log.info('sw', 'frontend-rpc external listener installed');
}

// The WS reverse-channel consumer (engine→extension `extension.invoke`
// servicing + catalog-stale refetch) lives in `@/lib/desktop/ws-invoke` —
// extracted so the protocol logic is unit-testable. Registered in
// bootstrapBackground() step 7.

/**
 * Pilot lifecycle listeners — CLAUDE.md roadmap item #9.
 *
 * The Pilot session ties an agent run to a specific Chrome tab group.
 * If that group disappears for any reason that didn't go through
 * `usePilotStore.endSession()` (user manually closed the last tab, user
 * removed the group from the strip, Chrome restored a session without it),
 * we need to reset the persisted record so the Pilot view UI doesn't keep
 * showing "session active" forever.
 *
 * Two signals catch every disappearance path:
 *   - `chrome.tabs.onRemoved` fires when the LAST tab in the group goes
 *     away; Chrome auto-removes the (now-empty) group. The check here
 *     scans the group: if zero tabs remain, reset.
 *   - `chrome.tabGroups.onRemoved` fires when the group is dissolved
 *     directly (user right-clicks → ungroup, etc.).
 *
 * Both listeners read the persisted session through the zustand store —
 * which itself is hydrated from `chrome.storage.local`, so the SW always
 * has the latest record even after a wake from idle.
 */
function registerPilotLifecycleListeners(): void {
  if (chrome.tabGroups?.onRemoved) {
    chrome.tabGroups.onRemoved.addListener((group) => {
      const session = usePilotStore.getState().session;
      if (session.active && session.groupId === group.id) {
        log.info('pilot', `tabGroups.onRemoved → resetting session group=${group.id}`);
        usePilotStore.getState().resetLocal();
      }
    });
  } else {
    log.warn(
      'pilot',
      'chrome.tabGroups.onRemoved unavailable — cannot watch for external group dissolution',
    );
  }
  if (chrome.tabs?.onRemoved) {
    chrome.tabs.onRemoved.addListener(async () => {
      const session = usePilotStore.getState().session;
      if (!session.active || session.groupId == null) return;
      // Has the group gone empty? Chrome auto-removes empty groups, but
      // tabGroups.onRemoved fires AFTER the last tab's onRemoved settles —
      // so on some platforms the group is briefly observable. Cheaper and
      // more robust to count surviving tabs.
      try {
        const survivors = await chrome.tabs.query({ groupId: session.groupId });
        if (survivors.length === 0) {
          log.info('pilot', 'tabs.onRemoved → group empty, resetting session');
          usePilotStore.getState().resetLocal();
        }
      } catch {
        /* the group may already be gone — onRemoved listener will catch it */
      }
    });
  }
}

/**
 * Close any offscreen document that survived an extension reload.
 *
 * MV3 offscreen documents are NOT torn down when the SW restarts (e.g. after
 * `pnpm build` + reload), so they can keep running stale JS while the rest
 * of the extension is on the new bundle. The most common symptom is the
 * audio path: sidepanel expects base64 strings (the post-50b09f9 contract)
 * but a stale offscreen still broadcasts ArrayBuffer, which
 * `chrome.runtime.sendMessage`'s JSON serializer flattens to `{}`. The
 * sidepanel's `base64ToBlob` then chokes on a non-string input.
 *
 * Closing here, once per SW boot, is the cheap blanket fix: the next
 * `ensureOffscreen()` call creates a fresh document with the latest code.
 * This is fire-and-forget — failures must never block bootstrap.
 */
async function closeStaleOffscreenOnBoot(): Promise<void> {
  try {
    // P1-15 guard: this runs on EVERY SW boot — including the routine ~30s
    // idle reap/rewake — and the offscreen doc is where the live SSE (and
    // mic capture) lives. Closing it during an in-flight run was killing
    // streams mid-execution; the 75s watchdog then mopped up a stall WE
    // caused. Skip the close while any recently-started run is live; a
    // 30-minute age-out keeps crash debris from pinning a genuinely stale
    // document forever.
    const stale = await staleOffscreenPreflight();
    if (!stale) return;
    // This is destructive to the singleton. Do not time-limit it: callers
    // remain behind the acquisition barrier until Chrome confirms the old
    // document is gone, so a late close can never destroy a fresh socket.
    await chrome.offscreen.closeDocument();
    log.info('sw', 'closed stale offscreen document on boot');
  } catch (err) {
    // Don't crash bootstrap — worst case the user runs into the original
    // stale-offscreen symptom and we surface it via the defensive base64
    // decoder guard instead.
    log.warn('sw', 'closeStaleOffscreenOnBoot failed', (err as Error)?.message);
  }
}

async function staleOffscreenPreflight(): Promise<boolean> {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  try {
    const result = await Promise.race<boolean | null>([
      staleOffscreenExists(),
      new Promise<null>((resolve) => {
        timeoutId = setTimeout(() => resolve(null), STALE_OFFSCREEN_PREFLIGHT_TIMEOUT_MS);
      }),
    ]);
    if (result === null) {
      log.warn('sw', 'stale offscreen preflight timed out; skipping cleanup');
      return false;
    }
    return result;
  } finally {
    if (timeoutId !== null) clearTimeout(timeoutId);
  }
}

async function staleOffscreenExists(): Promise<boolean> {
  // P1-15 guard: this runs on EVERY SW boot — including the routine ~30s
  // idle reap/rewake — and the offscreen doc is where the live SSE (and
  // mic capture) lives. Closing it during an in-flight run was killing
  // streams mid-execution; the 75s watchdog then mopped up a stall WE
  // caused. Skip the close while any recently-started run is live; a
  // 30-minute age-out keeps crash debris from pinning a genuinely stale
  // document forever.
  if (await hasRecentActiveStream(30 * 60_000)) {
    log.info('sw', 'offscreen has a live stream — skipping stale-close on boot');
    return false;
  }
  let exists = false;
  if (chrome.runtime.getContexts) {
    try {
      const contexts = await chrome.runtime.getContexts({
        contextTypes: ['OFFSCREEN_DOCUMENT' as chrome.runtime.ContextType],
      });
      exists = contexts.length > 0;
    } catch {
      /* fall through to hasDocument */
    }
  }
  if (!exists && 'hasDocument' in chrome.offscreen) {
    try {
      exists = await (chrome.offscreen as { hasDocument: () => Promise<boolean> }).hasDocument();
    } catch {
      /* fall through */
    }
  }
  if (!exists) log.info('sw', 'no stale offscreen to close');
  return exists;
}

/**
 * Phase 3c.1 — bring up the scheduler host once auth is ready.
 *
 * We read the stored UserProfile directly rather than calling getCurrentUser()
 * to avoid a circular module-load dependency (auth/flow imports many things
 * that import bootstrap indirectly). The shape is intentionally narrow —
 * just `id` — so any future profile changes don't drag this code along.
 *
 * No throw — scheduler-host failures must never block SW bootstrap.
 */
async function startSchedulerHostIfSignedIn(): Promise<void> {
  try {
    const r = await chrome.storage.local.get([STORAGE_KEYS.USER_PROFILE]);
    const profile = r[STORAGE_KEYS.USER_PROFILE] as UserProfile | undefined;
    if (profile?.id) {
      await startSchedulerHost(profile.id);
    } else {
      log.info('sys', 'scheduler-host: no signed-in user — not starting');
    }
  } catch (err) {
    log.warn('sys', `scheduler-host: bootstrap probe failed: ${(err as Error).message}`);
  }
}

/**
 * Watch chrome.storage.local for USER_PROFILE changes within this SW lifetime.
 *
 * Sign-in happens in the sidepanel context (chrome.identity is sidepanel-only
 * for us), so the SW won't see the sign-in directly — but it WILL see the
 * resulting storage write. Use that as the signal to (re)start the host.
 * Sign-out clears the key; we tear down on that same edge.
 */
/**
 * A person pressed "Re-discover" (Debug → Bridges) or saved a port override
 * (Settings → Desktop Bridge).
 *
 * This MUST run in the service worker. The discovery rate limits, the
 * bridge transport state and the socket are all worker state; a side panel
 * calling resetEngineDiscoveryBackoff() only cleared its own module copy,
 * so the button appeared to work while the background poll went on waiting
 * out its backoff and every tool stayed offline.
 */
function registerDesktopRediscoverHandler(): void {
  on<unknown, { transport: Transport; health: DesktopHealth | null; lastChecked: number }>(
    CHANNELS.DESKTOP_REDISCOVER,
    async () => {
      resetEngineDiscoveryBackoff();
      resetNativeProbeBackoff();
      await invalidateEnginePortCache();
      const state = await probeDesktop();
      lastDesktopTransport = state.transport;
      lastDesktopHealthKey = desktopHealthSnapshotKey(state.health);
      broadcast(CHANNELS.DESKTOP_AVAILABILITY, {
        transport: state.transport,
        health: state.health,
        lastChecked: state.lastChecked,
      });
      if (state.transport === 'http') void connectWs();
      return state;
    },
  );
}

function registerSchedulerHostUserWatcher(): void {
  if (!chrome.storage?.onChanged) return;
  chrome.storage.onChanged.addListener((changes, area) => {
    if (area !== 'local') return;
    const change = changes[STORAGE_KEYS.USER_PROFILE];
    if (!change) return;
    const next = change.newValue as UserProfile | undefined;
    if (next?.id) {
      void startSchedulerHost(next.id);
      void startAgendaScanner();
      // Sign-in occurs in the sidepanel, while the long-lived bridge clients
      // live here in the SW. Rehydrate this context before reconnecting
      // Broadcast or querying owner-RLS app_instances for a remote desktop.
      void rehydrateSupabaseSession().then(async () => {
        await connectBroadcast();
        const desktop = await probeDesktop();
        if (desktop.transport === 'http') void connectWs();
      });
    } else {
      void stopSchedulerHost();
      void stopAgendaScanner();
      void disconnectBroadcast();
      // Both holders are gone; drop the realm's realtime manager too. Its write
      // ledger and its actor identity belong to the user who just left, and a
      // manager kept across a user switch would classify the NEXT user's events
      // against the previous one's ledger.
      stopRealtimeHost();
      // Brokered grants belong to the user who minted them — drop the
      // in-memory credential cache the moment the profile clears.
      clearBrokerCacheOnSignOut();
    }
  });
}

async function rehydrateSupabaseSession(): Promise<void> {
  const stored = await chrome.storage.local.get([
    STORAGE_KEYS.ACCESS_TOKEN,
    STORAGE_KEYS.REFRESH_TOKEN_ENC,
    STORAGE_KEYS.REFRESH_TOKEN_IV,
  ]);
  const access = stored[STORAGE_KEYS.ACCESS_TOKEN] as string | undefined;
  if (!access) return;
  const { decryptString } = await import('@/lib/auth/crypto');
  const ct = stored[STORAGE_KEYS.REFRESH_TOKEN_ENC] as string | undefined;
  const iv = stored[STORAGE_KEYS.REFRESH_TOKEN_IV] as string | undefined;
  if (!ct || !iv) return;
  try {
    const refresh = await decryptString({ ct, iv });
    await setSupabaseSession(access, refresh);
  } catch (err) {
    console.warn('[matrx-extend] rehydrate failed', err);
  }
}
