/**
 * Agenda scanner — runs in the SW on a `chrome.alarms` cadence (every minute).
 *
 * Responsibilities:
 *   1. Find clock tasks whose `next_due_at <= now` and whose `surfaces`
 *      includes 'chrome-extension-chat' or 'any'. Covers one-shot, interval,
 *      heartbeat, and cron (next_due_at computed from the cron expression).
 *   2. Find context-match tasks and evaluate each against the active tab;
 *      fire the matches past their per-task cooldown (see context-match.ts).
 *   3. For each fired task, route to the sidepanel ('auto') or a Chrome
 *      notification ('ask').
 *   4. Advance the task's `next_due_at` for recurring clock triggers + stamp
 *      `last_run_at`, so we don't re-fire on the next scan.
 *
 * Why notification-driven for v0: programmatic agent invocation from the SW
 * touches the chat-stream pipeline and per-conversation state in non-trivial
 * ways. Shipping the loop notification-first lets users feel the timing
 * immediately and validates UX before we wire auto-execution.
 */

import { ALARMS, STORAGE_KEYS } from '@/config/env';
import { log } from '@/lib/debug/log';
import { send as msgSend } from '@/lib/messaging/native';
import { CHANNELS } from '@/lib/messaging/schemas';
import { hasFirefoxSidebarAction, openPanel, panelOpenRemedy } from '@/lib/panel/adapter';
import { cooldownElapsed, tabMatchesTask } from './context-match';
import {
  type AgendaTask,
  type TriggerConfig,
  claimDueFire,
  computeNextDueAfterRun,
  listContextMatchTasks,
  listDueForSurface,
  reapExpiredRuns,
} from './queries';

const NOTIFICATION_PREFIX = 'matrx-agenda:';
const SCAN_PERIOD_MIN = 1;

/**
 * Signed-out, every sch_task read runs as `anon` and Postgres answers
 * "permission denied for table sch_task" once a minute. The scanner is
 * therefore armed only while a session exists: signed-out it neither polls
 * nor keeps its alarm; the sign-in watcher in bootstrap re-arms it.
 */
async function hasSession(): Promise<boolean> {
  try {
    const stored = await chrome.storage.local.get([STORAGE_KEYS.ACCESS_TOKEN]);
    return !!stored[STORAGE_KEYS.ACCESS_TOKEN];
  } catch {
    return false;
  }
}

export async function startAgendaScanner(): Promise<void> {
  if (!(await hasSession())) {
    await stopAgendaScanner();
    return;
  }
  chrome.alarms.create(ALARMS.AGENDA_SCAN, { periodInMinutes: SCAN_PERIOD_MIN });
  // First scan immediately on SW boot too — the alarm period doesn't fire
  // until ~1 min after creation.
  void scanAndNotify();
}

/** Stop the scan timer (sign-out, or no session at boot). */
export async function stopAgendaScanner(): Promise<void> {
  await chrome.alarms.clear(ALARMS.AGENDA_SCAN).catch(() => undefined);
}

/**
 * Single-flight: the boot-time scan and an alarm-fired scan can overlap on
 * SW wake (the alarm event is exactly what woke the SW). Both reading the
 * same due set before either advanced it meant duplicate fires (audit P0-7).
 */
let scanInFlight: Promise<void> | null = null;

export function scanAndNotify(): Promise<void> {
  if (scanInFlight) return scanInFlight;
  scanInFlight = doScan().finally(() => {
    scanInFlight = null;
  });
  return scanInFlight;
}

async function doScan(): Promise<void> {
  // A stale alarm can outlive sign-out; never query as anon.
  if (!(await hasSession())) {
    await stopAgendaScanner();
    return;
  }
  let due: AgendaTask[] = [];
  try {
    due = await listDueForSurface('chrome-extension-chat', { limit: 10 });
  } catch (err) {
    log.warn('sw', 'agenda scan query failed', err);
    return;
  }
  if (due.length > 0) {
    log.info('sw', `agenda: ${due.length} task(s) due`);
    for (const task of due) {
      // Per-task isolation — one task throwing must not abort the rest of
      // the queue (or the context-match pass below). Audit P1-16.
      try {
        await fireDueTask(task);
      } catch (err) {
        log.warn('sw', `agenda: fireDueTask threw for ${task.id}`, err);
      }
    }
  }

  await scanContextMatch();

  // Fail-close runs whose lease expired with no surface finishing them —
  // without this, a stuck 'claimed' row blocks the task's unique-active-run
  // index forever. Best-effort, every scan.
  try {
    const reaped = await reapExpiredRuns();
    if (reaped > 0) log.info('sw', `agenda: reaped ${reaped} expired run(s)`);
  } catch (err) {
    log.warn('sw', 'agenda: reapExpiredRuns threw', err);
  }
}

/**
 * Context-match triggers fire on the active tab, not the clock — so they
 * never appear in `listDueForSurface` (no next_due_at). Fetch them, evaluate
 * each against the current active tab, and fire the matches that are past
 * their per-task cooldown.
 */
async function scanContextMatch(): Promise<void> {
  let tab: chrome.tabs.Tab | undefined;
  try {
    [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
  } catch {
    return;
  }
  if (!tab?.url || !/^https?:\/\//i.test(tab.url)) return;

  let hostname: string;
  try {
    hostname = new URL(tab.url).hostname;
  } catch {
    return;
  }
  const tabInfo = { url: tab.url, hostname };

  let tasks: AgendaTask[] = [];
  try {
    tasks = await listContextMatchTasks('chrome-extension-chat', { limit: 50 });
  } catch (err) {
    log.warn('sw', 'agenda context-match query failed', err);
    return;
  }

  for (const task of tasks) {
    if (!cooldownElapsed(task)) continue;
    if (!tabMatchesTask(task, tabInfo)) continue;
    log.info('sw', `agenda: context-match fired for "${task.title}" on ${hostname}`);
    try {
      await fireDueTask(task);
    } catch (err) {
      log.warn('sw', `agenda: context-match fire threw for ${task.id}`, err);
    }
  }
}

async function fireDueTask(task: AgendaTask): Promise<void> {
  // CLAIM FIRST, fire second (audit P0-7 / P2-15). The old order —
  // notify/broadcast, then advance next_due_at after the dispatch settled —
  // meant any run outlasting the 1-minute alarm period re-fired on the next
  // scan, and two scanners (boot + alarm, or two devices) both fired. The
  // CAS update makes exactly one scanner win; losing the race is the
  // expected outcome for everyone else. A crash between claim and fire is a
  // missed fire, never a duplicate — the right failure direction for
  // "agent acts on the user's behalf".
  const triggerConfig: TriggerConfig = {
    type: task.trigger_type,
    ...task.trigger_config,
  } as TriggerConfig;
  const next = computeNextDueAfterRun(triggerConfig);
  const claimed = await claimDueFire(task, {
    next_due_at: next ?? null,
    last_run_at: new Date().toISOString(),
    // One-shot tasks auto-disable after firing.
    enabled: task.trigger_type === 'one-shot' ? false : task.enabled,
  });
  if (!claimed) {
    log.info('sw', `agenda: lost the fire claim for ${task.id} (another scanner won)`);
    return;
  }

  // Auto mode: try the live sidepanel first. If it acks, the run starts
  // there immediately (no notification, no click). If nothing acks within
  // a short window, fall back to a notification so the user still sees
  // the task became due.
  if (task.auth_mode === 'auto') {
    const routedToSidepanel = await tryBroadcastRunNow(task.id);
    if (!routedToSidepanel) await notifyDue(task);
  } else {
    await notifyDue(task);
  }
}

/**
 * Returns true if the sidepanel was open and ack'd the broadcast. Uses
 * the request/response `send` so chrome.runtime.sendMessage rejects when
 * no listener is registered (sidepanel closed) — that's our fallback
 * signal to drop a notification instead.
 */
async function tryBroadcastRunNow(taskId: string): Promise<boolean> {
  try {
    const r = await msgSend<{ taskId: string }, { ack: true } | undefined>(
      CHANNELS.AGENDA_RUN_NOW,
      { taskId },
      // A closed side panel is the answer this call is asking for, not a
      // fault: we fall back to an OS notification below.
      { absenceIsAnAnswer: true },
    );
    return !!r && (r as { ack?: boolean }).ack === true;
  } catch {
    return false;
  }
}

async function notifyDue(task: AgendaTask): Promise<void> {
  const id = `${NOTIFICATION_PREFIX}${task.id}`;
  try {
    await chrome.notifications.create(id, {
      type: 'basic',
      iconUrl: chrome.runtime.getURL('icon-128.png'),
      title: `Agenda: ${task.title}`,
      message: task.description ?? 'Task is due. Click to open the Agenda tab.',
      priority: 1,
      requireInteraction: false,
    });
  } catch (err) {
    log.warn('sw', `agenda notify failed for ${task.id}`, err);
  }
}

/**
 * Wired from SW bootstrap. On notification click → open the sidepanel and
 * focus the Agenda tab. The sidepanel reads the focused-task id from
 * chrome.storage.session and scrolls/highlights it.
 */
export function registerAgendaNotificationClicks(): void {
  if (!chrome.notifications) return;
  chrome.notifications.onClicked.addListener(async (notificationId) => {
    if (!notificationId.startsWith(NOTIFICATION_PREFIX)) return;
    const taskId = notificationId.slice(NOTIFICATION_PREFIX.length);
    try {
      // Surface a hint for the sidepanel to focus this task.
      await chrome.storage.session?.set({ 'matrx.agenda.focus_task_id': taskId });
    } catch {
      /* storage.session can be absent on older Chrome; ignore */
    }
    // Open the sidepanel — chrome.sidePanel.open requires a windowId in MV3.
    try {
      if (hasFirefoxSidebarAction()) {
        await showAgendaPanelRemedy(notificationId);
        return;
      }
      const win = await chrome.windows.getCurrent();
      if (win.id == null) {
        await showAgendaPanelRemedy(notificationId);
        return;
      }
      const attempt = openPanel({ windowId: win.id });
      if (!attempt.promise) {
        await showAgendaPanelRemedy(notificationId, panelOpenRemedy(attempt.reason));
        return;
      }
      await attempt.promise;
      chrome.notifications.clear(notificationId);
    } catch (err) {
      log.warn('sw', 'sidePanel.open failed on notification click', err);
      await showAgendaPanelRemedy(
        notificationId,
        panelOpenRemedy((err as Error)?.message ?? 'open-failed'),
      );
    }
  });
}

/** Keep the clicked notification visible and turn it into the Firefox remedy. */
async function showAgendaPanelRemedy(notificationId: string, reason?: string): Promise<void> {
  const message = reason ?? 'Open Matrx from the toolbar or right-click menu.';
  try {
    await chrome.notifications.update(notificationId, {
      title: 'Matrx needs the toolbar to open',
      message,
      requireInteraction: true,
    });
  } catch (err) {
    log.warn('sw', 'could not keep agenda remedy visible', err);
  }
}
